// Poda Fase 4.1 (ic_salon): fluxo sales_v1 / Genesis (bloco 11: executeCommercialDecision .. salesReadMedia) removido.
async function queueRpc(name, extra = {}) {
  // Check the paired deployment before claim can mutate the queue. The claim
  // response check remains mandatory for fencing and rollout races.
  if (name === 'claim') {
    if (!env('NORIA_INGRESS_FORWARD_TOKEN_' + tenantEnvSuffix(tenantSlug))) {
      throw new Error('TURN_INGRESS_CONFIG_REQUIRED');
    }
    let readiness;
    try {
      readiness = await supabaseGet('/rest/v1/rpc/magia_turn_lifecycle_status');
    } catch (error) {
      throw new Error('TURN_LIFECYCLE_DEPLOYMENT_REQUIRED:' + String(error?.message || error).slice(0, 160));
    }
    if (readiness?.ready !== true || readiness.contract !== 'noria_turn_lifecycle_v1') {
      throw new Error('TURN_LIFECYCLE_DEPLOYMENT_REQUIRED');
    }
  }
  return supabasePost('/rest/v1/rpc/magia_' + name + '_turn', {
    p_tenant: inputJson.tenant_id, p_chat: chatId, ...(turn?.token ? { p_token: turn.token } : {}), ...extra,
  });
}

async function complete(outcome) {
  if (turnFinished) throw new Error('TURN_ALREADY_FINISHED');
  if (outcome === 'retry') {
    const queue = await turnQueueState();
    if (queue?.token !== turn?.token || queue?.phase !== 'processing'
      || turnCommitted || sendAttempted || providerAccepted || deliveryConfirmed) {
      throw new Error('TURN_RETRY_REQUIRES_PROCESSING');
    }
  }
  if (outcome === 'done' && sendAttempted && !deliveryConfirmed) throw new Error('TURN_DELIVERY_NOT_CONFIRMED');
  const result = await queueRpc('finish', { p_outcome: outcome });
  if (result?.finished !== true) throw new Error('TURN_FINISH_NOT_PERSISTED');
  if (result.contract !== 'noria_turn_lifecycle_v1') throw new Error('TURN_LIFECYCLE_RPC_MISMATCH');
  turnFinished = ['done', 'cancelled', 'ready'].includes(result.outcome);
  if (['done', 'cancelled'].includes(outcome) && result.outcome !== outcome) {
    throw new Error('TURN_TERMINAL_NOT_PROVEN:' + String(result.reason || result.outcome));
  }
  if (outcome === 'retry' && result.retry_queued !== true) {
    throw new Error('TURN_RETRY_NOT_QUEUED:' + String(result.reason || result.outcome));
  }
  return result;
}

async function turnQueueState() {
  const rows = await supabaseGet('/rest/v1/conversation_turn_queue?select=phase,token,lease_until'
    + '&tenant_id=eq.' + encodeFilter(inputJson.tenant_id)
    + '&channel_type=eq.whatsapp&chat_id=eq.' + encodeFilter(chatId) + '&limit=1');
  return rows?.[0] || null;
}

async function commit() {
  if (turnCommitted || sendAttempted || turnFinished) throw new Error('TURN_COMMIT_STATE_INVALID');
  const result = await queueRpc('commit');
  if (result?.committed !== true) {
    if (!['new_messages', 'conversation_control_changed'].includes(result?.reason)) {
      throw new Error('TURN_COMMIT_NOT_CONFIRMED:' + String(result?.reason || 'unknown'));
    }
    await complete(result.reason === 'new_messages' ? 'retry' : 'cancelled');
    return false;
  }
  turnCommitted = true;
  if (result.contract !== 'noria_turn_lifecycle_v1') throw new Error('TURN_LIFECYCLE_RPC_MISMATCH');
  return true;
}

async function runTurn() {
  if (!tenantSlug || !chatId || !inputJson.tenant_id) throw new Error('Missing scoped input');
  // core-preclaimed-turn-dispatch-v1
  const preclaimed = inputJson.noria_preclaimed_turn;
  if (preclaimed !== undefined) {
    if (!preclaimed || typeof preclaimed !== 'object') throw new Error('NORIA_PRECLAIMED_TURN_INVALID');
    turn = preclaimed;
    if (turn.claimed === true) {
      if (!Array.isArray(turn.messages) || !String(turn.token || '') || !String(turn.boundary_id || '')) throw new Error('NORIA_PRECLAIMED_TURN_INVALID');
      const dispatched = inputJson.noria_business_context;
      if (!dispatched || typeof dispatched !== 'object') {
        // A contract-version refusal by the EXT identity (publication gap between CORE and EXT) is tagged so the failure path can
        // classify it as a pre-send, retryable cutover condition. Any other EXT dispatch failure keeps its previous handling.
        if (inputJson.error) throw new Error('NORIA_EXT_DISPATCH_UNAVAILABLE' + (CONTRACT_CUTOVER_PATTERN.test(String(inputJson.error?.message || inputJson.error || '')) ? ':CONTRACT_VERSION' : ''));
        throw new Error('NORIA_TURN_DISPATCH_STALE');
      }
      if (dispatched.phase === 'bootstrap' || dispatched.session_id !== turn.boundary_id
        || !String(dispatched.request_id || '').endsWith(':' + String(turn.token))) throw new Error('NORIA_TURN_DISPATCH_STALE');
    }
  }
  if (turn && !turn.claimed) return { ok: true, skipped: true, reason: turn.reason };
  // Capture an already claimed EXT token before fallible setup. New claims
  // still require the original policy, tenant and credential validation first.
  validateTenantPolicyContract();
  const context = await loadTenantContext();
  const liveSettings = settingsFor(context);
  if ((tenantBusinessRules.capability === 'sales_v1') !== (liveSettings.conversation_capability === 'sales_v1')
    || tenantBusinessRules.audio_enabled !== (liveSettings.whatsapp_audio_enabled === true)
    || tenantBusinessRules.scheduling_enabled !== (liveSettings.appointment_scheduling?.enabled === true)) {
    throw new Error('NORIA_POLICY_OUTDATED_RETRY');
  }
  const suffix = tenantEnvSuffix(tenantSlug);
  if (!env('EVOLUTION_API_URL_' + suffix) || !env('EVOLUTION_API_KEY_' + suffix)
    || env('EVOLUTION_INSTANCE_' + suffix) !== inputJson.instance) throw new Error('Configure tenant Evolution environment first');
  // Poda Fase 4.1 (ic_salon): pipeline multifase (services_v1 / NORIA_TURN_PIPELINE) desabilitado; apenas fase 'single'.
  if (!turn) turn = await queueRpc('claim');
  if (!turn.claimed) return { ok: true, skipped: true, reason: turn.reason };
  if (turn.contract !== 'noria_turn_lifecycle_v1') throw new Error('TURN_LIFECYCLE_RPC_MISMATCH');
  await refreshTurnSuppressionEvidence();
  // magia_enqueue_turn keeps the compact queue payload intentionally small.
  // Re-hydrate raw_payload from channel_events after claim so referral/ad context,
  // media metadata and suppression flags survive into the current turn.
  try {
    const eventIds = [...new Set((turn.messages || []).map(item => item?.event_id).filter(Boolean))];
    if (eventIds.length) {
      const rows = await supabaseGet('/rest/v1/channel_events?select=id,raw_payload&tenant_id=eq.' + encodeFilter(inputJson.tenant_id)
        + '&channel_type=eq.whatsapp&external_conversation_id=eq.' + encodeFilter(chatId)
        + '&id=in.(' + eventIds.map(encodeFilter).join(',') + ')');
      const rawById = new Map((rows || []).map(row => [row.id, row.raw_payload && typeof row.raw_payload === 'object' ? row.raw_payload : {}]));
      turn.messages = (turn.messages || []).map(item => ({ ...item, raw: rawById.get(item.event_id) || item.raw || {} }));
    }
  } catch (_) { /* referral/media hydration is fail-soft; canonical event stays persisted */ }
  message.message_id = turn.messages.at(-1).id;
  setCurrentText(turn.messages.map(item => item.text).filter(Boolean).join('\n\n'));
  originalTextOrCaption = displayMessageText = rawText;
  const controlHistory = await loadRecentHistory(context);
  if (turn.history_boundary_changed) {
    await complete('cancelled'); return { ok: true, skipped: true, reason: 'attendance_changed' };
  }
  if (turn.boundary_created_at) {
    const obsolete = turn.messages.filter(item => Date.parse(item.received_at) <= Date.parse(turn.boundary_created_at));
    if (obsolete.length) {
      await supabasePatch('/rest/v1/channel_events?tenant_id=eq.' + encodeFilter(inputJson.tenant_id)
        + '&id=in.(' + obsolete.map(item => encodeFilter(item.event_id)).join(',') + ')',
        { stage: 'Finalizado', ai_provider: 'cancelled_before_close', response_text: null });
      turn.messages = turn.messages.filter(item => !obsolete.includes(item));
      if (!turn.messages.length) { await complete('cancelled'); return { ok: true, skipped: true, reason: 'closed_before_processing' }; }
      setCurrentText(turn.messages.map(item => item.text).filter(Boolean).join('\n\n'));
    }
  }
  const control = conversationControl(controlHistory);
  const verifiedControl = turn.suppression_evidence?.human_control;
  control.lockedByHuman = !!verifiedControl;
  control.lockEvent = verifiedControl ? controlHistory.find(row => row.id === verifiedControl.event_id) || null : null;
  control.lockSource = verifiedControl ? 'persisted_control' : null;
  const settings = settingsFor(context);
  // Poda Fase 4.1 (ic_salon): grounding_mode nunca e 'canonical_v2'.
  const history = control.activeHistory.slice(-12);
  const event = {
    tenant_id: context.tenant.id, tenant_slug: tenantSlug, channel_type: 'whatsapp',
    service: 'geral', stage: 'Conversas IA', handoff: false, ai_provider: 'rules', raw_payload: {}
  };

  const exclusion = await contactExclusionStatus(context);
  if (exclusion.blocked) {
    if (exclusion.reason === 'contact_excluded' && !turn.suppression_evidence?.contact_excluded) await refreshTurnSuppressionEvidence();
    if (exclusion.reason !== 'contact_excluded' || !turn.suppression_evidence?.contact_excluded) {
      throw new Error('CONTACT_EXCLUSION_AUTHORITY_UNAVAILABLE');
    }
    if (!await commit()) return { ok: true, skipped: true, reason: 'superseded' };
    await recordContactExclusion(context, exclusion);
    await complete('done');
    return { ok: true, skipped: true, reason: exclusion.reason };
  }

  // Prova de não cliente é vinculada ao turno e vale para qualquer capacidade.
  if (turn.suppression_evidence?.non_customer) {
    if (!await commit()) return { ok: true, skipped: true, reason: 'superseded' };
    Object.assign(event, { ai_provider: 'non_customer_suppression', service: 'non_customer', handoff: false,
      raw_payload: { ...(event.raw_payload || {}), ai_suppressed: true, ai_suppressed_reason: 'validated_non_customer', suppression_scope: 'current_turn_only' } });
    await cancelPendingFollowUps(context, 'validated_non_customer');
    await saveEvent(event); await complete('done');
    return { ok: true, skipped: true, reason: 'validated_non_customer' };
  }

  // Delivered far too late (e.g. after a WhatsApp reconnect): recorded for the team, no automatic reply and no follow-up.
  const staleTurn = noriaPhase === 'finalize' ? null : turnStaleMessages(turn.messages, settings);
  if (staleTurn) {
    if (!await commit()) return { ok: true, skipped: true, reason: 'superseded' };
    Object.assign(event, { ai_provider: 'stale_message_suppression', service: 'stale_message', handoff: false,
      raw_payload: { ...(event.raw_payload || {}), ai_suppressed: true, ai_suppressed_reason: 'stale_message', stale_message: staleTurn } });
    await saveEvent(event); await complete('done');
    return { ok: true, skipped: true, reason: 'stale_message' };
  }

  const contact = await loadContact(context);
  if (isCommercialContact(contact, turn)) {
    if (!await commit()) return { ok: true, skipped: true };
    event.ai_provider = 'non_customer_suppression';
    event.handoff = false;
    event.stage = 'Número comercial';
    event.service = 'non_customer';
    event.raw_payload = {
      ...(event.raw_payload || {}),
      ai_suppressed: true,
      ai_suppressed_reason: 'commercial_number',
      is_commercial: true,
      contact_category: 'commercial',
      contact_category_label: 'Número comercial',
    };
    await cancelPendingFollowUps(context, 'commercial_number');
    await saveEvent(event);
    await complete('done');
    return { ok: true, skipped: true, ai_suppressed: true, reason: 'commercial_number' };
  }
  if (shouldIgnoreBecauseOwnerSavedContact(contact, turn)) {
    if (!await commit()) return { ok: true, skipped: true };
    event.ai_provider = 'owner_saved_suppression';
    event.handoff = false;
    event.stage = 'Atendimento humano';
    event.service = 'atendimento_humano';
    event.raw_payload = {
      ...(event.raw_payload || {}),
      ai_suppressed: true,
      ai_suppressed_reason: 'owner_saved_contact',
      is_owner_saved: true,
      contact_category: 'saved',
      contact_category_label: 'Contato salvo',
      owner_saved_source: turn.suppression_evidence.owner_saved_contact.source,
      owner_saved_authority: turn.suppression_evidence.owner_saved_contact,
    };
    await cancelPendingFollowUps(context, 'owner_saved_contact');
    await saveEvent(event);
    await complete('done');
    return { ok: true, skipped: true, ai_suppressed: true, reason: 'owner_saved_contact' };
  }

  // Poda Fase 4.1 (ic_salon): salesEnabled(context) e pipeline multifase (services_v1) removidos por serem inalcancaveis no Salon.

  if (normalized === '/reset' || normalized === 'reset') {
    if (!await commit()) return { ok: true, skipped: true };
    event.ai_provider = 'conversation_reset'; event.service = 'conversation_closed'; event.stage = 'Reset';
    await saveEvent(event);
    const sent = await sendChannelMessage(context, 'Conversa reiniciada. Pode mandar sua próxima mensagem.', event);
    await complete('done'); return { ok: true, ...sent };
  }
  // Handoff is persistent across messages; SINAL PAGO is acknowledged only once.
  if (control.lockedByHuman) {
    if (!await commit()) return { ok: true, skipped: true };
    event.ai_provider = 'human_lock'; event.handoff = true;
    event.stage = control.lockEvent?.stage || 'Atendimento humano';
    event.service = control.lockEvent?.service || 'atendimento_humano';
    await saveEvent(event); await complete('done');
    return { ok: true, human_lock: true, skipped: true };
  }
  try {
    await transcribeTurnAudio(context);
  } catch (error) {
    if (!await commit()) return { ok: true, skipped: true, reason: 'superseded' };
    Object.assign(event, {
      ai_provider: 'audio_handoff', handoff: true, stage: 'Atendimento humano', service: 'atendimento_humano',
      ai_error: String(error.message).slice(0, 160)
    });
    await saveEvent(event);
    const sent = await sendChannelMessage(context, await composeMediaNotice(context, history, 'audio_failed_handoff',
      'Recebi seu \u00e1udio, mas n\u00e3o consegui processar com seguran\u00e7a agora. S\u00f3 um momentinho, vou chamar a equipe para continuar com voc\u00ea.', { handoff: true }), event);
    await complete('done'); return { ok: true, handoff: event.handoff, ...sent };
  }
  if (isPaymentSignalPaidText(rawText, context)) {
    if (!await commit()) return { ok: true, skipped: true };
    const update = await markLatestAppointmentPaymentReported(context);
    Object.assign(event, {
      service: 'pagamento_sinal', stage: paymentSignalStageFor(context),
      handoff: true, ai_provider: 'payment_signal', raw_payload: {
        payment_signal: {
          appointment_update: update,
          pending_confirmation_message: paymentSignalConfirmationMessage(context)
        }
      }
    });
    await saveEvent(event);
    const sent = await sendChannelMessage(context, paymentSignalAckMessage(context), event);
    await complete('done'); return { ok: true, handoff: true, ...sent };
  }

  const requestConfig = appointmentRequestConfig(context);
  const contextualBooking = requestConfig?.valid && requestConfig.reply_mode === 'contextual';
  const appointmentResult = await loadAppointments(context.tenant.id, false, contextualBooking);
  const appointments = appointmentState(appointmentResult.rows);
  if (requestConfig?.valid) await refreshOpenAppointmentRequests(context, appointments);
  const catalog = await loadCatalogContext(context);
  if (catalog.error || !catalog.matches?.length) throw new Error('Service catalog unavailable');
  const gate = usageGate(context);
  let responseText;
  let preserveLiteralReply = false;
  let literalReplySuffix = '';
  let needsTeamReview = false;
  let slotDecision = null;
  let slotResolutionTurn = false;
  // Poda Fase 4.1 (ic_salon): grounding_mode nunca e 'canonical_v2'; ramo canonical_v2/callGroundedGemini/ignoreAutomatedContact removido.
  if (!gate.allowed) {
    responseText = sessionHandoffMessage(context);
    event.ai_provider = 'fallback_daily_limit'; event.handoff = true; event.stage = 'Atendimento humano';
    event.raw_payload.ai_availability = sessionUsageDiagnostic(gate);
    event.ai_error = event.raw_payload.ai_availability.reason;
  } else {
    if (contextualBooking) {
      const lookup = await salonSlotProposalDecisionSafely(context, history, turn.messages);
      slotDecision = lookup.decision;
      if (lookup.skipped) event.raw_payload.slot_proposal_resolution = { skipped: lookup.skipped };
    }
    const generated = await callGemini(context, '', history, catalog, appointments);
    markUsage();
    responseText = generated.text; event.ai_provider = generated.transient_failure ? 'gemini_degraded' : 'gemini'; event.ai_model = generated.model; event.ai_usage = generated.usage;
    needsTeamReview = !event.handoff && generated.needsTeamReview === true;
    if (generated.transient_failure) { event.ai_error = 'GEMINI_TRANSIENT_FAILURE'; event.raw_payload.generation_failure = generated.transient_failure; event.raw_payload.ai_processing_ok = false; }
    preserveLiteralReply = generated.preserveLiteral === true;
  }
  // No appointment or payment side effect before fencing stale model output.
  if (!await commit()) return { ok: true, skipped: true, reason: 'superseded' };
  if (slotDecision && !event.handoff) {
    const outcome = await salonResolveSlotProposalSafely(context, slotDecision);
    const resolved = outcome.resolved;
    if (resolved) {
      // A proposta aceita volta a ser pedido pendente; a recusada deixa de ser. Os pedidos das outras pessoas seguem como estão.
      const others = (appointments.openRequests || []).filter(item => item.id !== resolved.appointment?.id);
      appointments.openRequests = slotDecision.decision === 'accept' ? [...others, resolved.appointment] : others;
      appointments.openRequest = appointments.openRequests.at(-1) || null;
    }
    event.raw_payload.slot_proposal_resolution = { proposal_id: slotDecision.proposal_id, decision: slotDecision.decision,
      turn_event: slotDecision.turn_event, appointment_id: slotDecision.appointment_id, already: resolved?.already === true,
      ...(outcome.refused ? { refused: outcome.refused } : {}) };
    const instruction = outcome.refused
      ? '\n\nFATO OPERACIONAL: a proposta de horário enviada antes não pôde ser aplicada agora (ela já foi resolvida, substituída, venceu ou existe outro pedido em aberto nesta conversa). Nada foi registrado nem confirmado. Responda naturalmente à mensagem atual, sem tag de agendamento, e diga que a equipe confere o horário por aqui.'
      : slotDecision.decision === 'accept'
        ? '\n\nFATO OPERACIONAL: o cliente aceitou a proposta e o pedido foi encaminhado novamente à equipe para confirmação. Ainda não existe confirmação nem reserva garantida. Responda naturalmente sem tag de agendamento.'
        : '\n\nFATO OPERACIONAL: o cliente recusou a proposta; o horário não foi reservado. Responda naturalmente à mensagem atual sem tag de agendamento.';
    const revised = await callGemini(context, '', history, catalog, appointments, instruction);
    markUsage();
    responseText = revised.text;
    event.ai_model = revised.model;
    event.ai_usage = revised.usage;
    const revisedState = salonRevisedTurnState(revised, event.handoff);
    preserveLiteralReply = revisedState.preserveLiteralReply;
    needsTeamReview = revisedState.needsTeamReview;
    slotResolutionTurn = true;
  }
  const actions = detectActions(responseText);
  // O Gemini decide que o cliente quer o catálogo completo e sinaliza com a tag; a lista oficial vem do banco (nunca da prosa).
  if (actions.catalogRequested && catalog.isComplete) {
    // A abertura é a prosa do modelo só quando ela é uma frase curta; lista escrita pelo modelo duplicaria a lista oficial.
    const opening = cleanReplyText(responseText).trim();
    const intro = opening && opening.length <= 320 && !opening.includes('\n') ? opening : '';
    responseText = buildFullCatalogReplyFromRows(catalog.matches, intro, actions.catalogPricesRequested);
    event.ai_provider = 'catalog_db_direct';
  }
  const tag = parseAppointmentCreationTag(responseText);
  let creation = null;
  // No turno em que a proposta foi resolvida, tag de agendamento da segunda geração não cria nem altera pedido.
  const requestAction = requestConfig && !slotResolutionTurn ? parseAppointmentRequestAction(responseText) : null;
  // Criar e, no modo contextual, cancelar um pedido ainda não confirmado pela equipe são gravados pela IA; alterar segue com a equipe.
  const writableRequestAction = requestAction?.kind === 'create' || (requestAction?.kind === 'cancel' && contextualBooking);
  if (!event.handoff && writableRequestAction && !actions.humanRequested && !actions.complaint) {
    try {
      if (!requestConfig.valid) throw new Error('APPOINTMENT_REQUEST_CONFIG_INVALID');
      if (requestAction.kind === 'cancel') {
        if (!cleanReplyText(responseText).trim()) throw new Error('APPOINTMENT_REQUEST_EMPTY_REPLY');
        const cancelled = contextualBooking ? await cancelContextualAppointmentRequest(context, selectOpenAppointmentRequest(appointments.openRequests, requestAction))
          : await supabasePost('/rest/v1/rpc/magia_cancel_appointment_request', { p_tenant: context.tenant.id, p_channel: 'whatsapp',
            p_chat: String(chatId), p_reason: 'customer_cancelled', p_actor: 'ai' });
        event.raw_payload.appointment_request = { kind: 'cancel', cancelled: cancelled?.cancelled === true, appointment_id: cancelled?.appointment?.id || null };
        if (cancelled?.cancelled !== true) throw new Error('APPOINTMENT_REQUEST_NOT_OPEN');
        event.service = 'agendamento_cancelado';
      } else {
        const request = await saveAppointmentRequest(context, requestAction,
          requestAction.kind === 'update' ? selectOpenAppointmentRequest(appointments.openRequests, requestAction) : null, appointments.openRequests || []);
        const template = (requestAction.kind === 'update' || request.name_completed === true) && requestConfig.reply_mode === 'contextual'
          && typeof requestConfig.updated_template === 'string' && requestConfig.updated_template.trim()
          ? requestConfig.updated_template : requestConfig.received_template;
        const received = renderAppointmentRequest(template, request, context);
        responseText = received; preserveLiteralReply = true;
        event.service = 'agendamento_pendente'; event.stage = 'Aguardando confirmação';
        event.raw_payload.appointment_request = { kind: requestAction.kind, appointment_id: request.id, request_version: request.metadata?.request_version || null };
        appointments.openRequests = [...(appointments.openRequests || []).filter(item => item.id !== request.id), request];
        appointments.openRequest = request;
      }
    } catch (error) {
      const code = supabaseErrorText(error) || String(error?.message || error);
      event.ai_error = 'appointment_not_created';
      event.raw_payload.appointment_request = { kind: requestAction.kind, failed: String(code).slice(0, 120) };
      // A frase de nova tentativa é do tenant (appointment_request no Supabase); o código só classifica o erro técnico.
      const retryKey = /APPOINTMENT_FULL_NAME_REQUIRED/.test(code) ? 'full_name_template'
        : /Invalid appointment details|APPOINTMENT_REQUEST_PAST/.test(code) ? 'missing_details_template' : '';
      const retryText = retryKey ? salonLiteralTemplate(context, retryKey) : '';
      if (contextualBooking && requestAction.kind === 'cancel' && /APPOINTMENT_REQUEST_NOT_OPEN/.test(code)) {
        // Não há pedido pendente dessa pessoa: nada a retirar e nada para a equipe; o modelo explica sem afirmar cancelamento.
        const revised = await callGemini(context, '', history, catalog, appointments,
          '\n\nCORREÇÃO OPERACIONAL: não há pedido pendente dessa pessoa para retirar, e nenhum pedido foi cancelado neste turno. Os pedidos de outras pessoas continuam como estão. Diga isso com naturalidade, sem afirmar que retirou, cancelou ou removeu algo, e pergunte se pode ajudar em mais alguma coisa. Não emita tag de agendamento.');
        // Uma segunda tentativa antes do texto de erro (o primeiro reparo às vezes volta com tag ou vazio).
        // A reescrita que já desistiu (texto de erro do tenant) também não serve: segue para o recurso próprio do caso.
        const usable = text => !parseAppointmentRequestAction(text) && Boolean(cleanReplyText(text).trim())
          && ![salonLiteralTemplate(context, 'processing_error_template'), salonLiteralTemplate(context, 'review_handoff_template')]
            .includes(cleanReplyText(text).trim());
        const second = usable(revised.text) ? revised : await callGemini(context, '', history, catalog, appointments,
          '\n\nCORREÇÃO OPERACIONAL: não há pedido pendente dessa pessoa para retirar e nada foi cancelado. Responda em uma frase curta, sem tag, sem dizer que retirou ou cancelou algo, e pergunte se pode ajudar em mais alguma coisa.');
        responseText = usable(second.text) ? second.text
          : salonConfiguredTemplate(context, 'no_pending_request_template') || salonLiteralTemplate(context, 'processing_error_template');
        preserveLiteralReply = !usable(second.text);
      } else if (contextualBooking && /APPOINTMENT_REQUEST_(?:CHANGED|NOT_OPEN|BUSY)/.test(code)) {
        const current = appointmentState((await loadAppointments(context.tenant.id, false, true)).rows);
        await refreshOpenAppointmentRequests(context, current);
        const revised = await callGemini(context, '', history, catalog, current,
          '\n\nCORREÇÃO OPERACIONAL: nada foi gravado: o pedido desta mensagem não foi registrado, alterado nem cancelado, e os pedidos já existentes seguem como estão no estado atual. Não diga nem sugira que o pedido foi registrado, anotado, enviado ou encaminhado, e não diga que a equipe vai confirmar este dia, horário ou serviço. Explique com naturalidade que não foi possível registrar agora e que a equipe foi avisada para falar com a pessoa por aqui. Não emita tag de agendamento.');
        // Texto com tag de agendamento ou vazio nunca sai: sem registro, só o texto de erro do tenant.
        if (parseAppointmentRequestAction(revised.text) || !cleanReplyText(revised.text).trim()) {
          responseText = salonLiteralTemplate(context, 'processing_error_template'); preserveLiteralReply = true;
        } else responseText = revised.text;
        event.handoff = true;
        event.stage = 'Atendimento humano';
        event.service = 'atendimento_humano';
      } else if (/outside_business_hours|past_date_time|APPOINTMENT_REQUEST_PAST|APPOINTMENT_FULL_NAME_REQUIRED/.test(code)) {
        // Nada foi gravado: o modelo explica o motivo certo e pede só o que falta, sem tag. Duas tentativas; o texto fixo do
        // tenant fica como último recurso (ele dizia "o seu nome" mesmo quando faltava o sobrenome de outra pessoa).
        const reason = /outside_business_hours/.test(code)
          ? 'o dia ou horário proposto está fora do horário de funcionamento configurado (o que inclui feriados em que o salão fecha). Explique com naturalidade e peça outro dia ou horário dentro do funcionamento.'
          : /APPOINTMENT_FULL_NAME_REQUIRED/.test(code)
            ? 'falta o nome completo, com sobrenome, da pessoa que será atendida (' + (requestAction.customerName || 'nome informado') + '). Peça só o sobrenome ou o nome completo dessa pessoa, sem pedir o nome de quem escreve.'
            : 'o dia e o horário entendidos já passaram. Explique com naturalidade e pergunte qual dia e horário futuro a pessoa prefere (um dia da semana sem data é a próxima ocorrência futura).';
        const instruction = '\n\nCORREÇÃO OPERACIONAL: nada foi registrado: ' + reason + ' Não diga que registrou e não emita tag de agendamento.';
        // A reescrita que já desistiu (texto de erro do tenant) também não serve: segue para o recurso próprio do caso.
        const usable = text => !parseAppointmentRequestAction(text) && Boolean(cleanReplyText(text).trim())
          && ![salonLiteralTemplate(context, 'processing_error_template'), salonLiteralTemplate(context, 'review_handoff_template')]
            .includes(cleanReplyText(text).trim());
        let revised = await callGemini(context, '', history, catalog, appointments, instruction);
        if (!usable(revised.text)) revised = await callGemini(context, '', history, catalog, appointments, instruction + ' A tentativa anterior não pôde ser usada: escreva só uma mensagem curta, sem tag.');
        if (usable(revised.text)) responseText = revised.text;
        else {
          const closedText = /outside_business_hours/.test(code) ? salonConfiguredTemplate(context, 'closed_day_template') : '';
          responseText = closedText || retryText || salonLiteralTemplate(context, 'processing_error_template'); preserveLiteralReply = true;
        }
      } else if (retryText) {
        responseText = retryText; preserveLiteralReply = true;
      } else {
        // Pedido em envio, configuração inválida ou falha técnica: decide uma pessoa, com texto visível do tenant.
        responseText = salonLiteralTemplate(context, 'processing_error_template'); preserveLiteralReply = true;
        event.handoff = true; event.stage = 'Atendimento humano'; event.service = 'atendimento_humano';
      }
    }
  } else if (tag && !requestConfig) {
    try {
      // Require an actual active service, full identity and a valid future date.
      const services = await supabaseGet('/rest/v1/tenant_service_catalog?select=name&tenant_id=eq.'
        + encodeFilter(context.tenant.id) + '&active=eq.true&limit=100');
      const service = services.find(item => normalizeText(item.name) === normalizeText(tag.service));
      const starts = parseAppointmentStartAt(tag.date, tag.time, context);
      const roundtrip = starts && new Intl.DateTimeFormat('en-CA', { timeZone: tenantTimeZone(context), year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(starts));
      if (!groundingIsFullName(tag.customerName)) throw new Error('APPOINTMENT_FULL_NAME_REQUIRED');
      if (!service || !starts || Date.parse(starts) <= Date.now()
        || (/^\d{4}-\d{2}-\d{2}$/.test(tag.date) && roundtrip !== tag.date)) throw new Error('Invalid appointment details');
      tag.service = service.name;
      // Poda Fase 4.1 (ic_salon): appointment_scheduling e canonical_v2 inativos; reserva legada direta sem schedulingReserve/composeSchedulingOutcomeReply.
      creation = await createAppointmentFromTag(context, tag, tag.customerName);
      if (!creation.appointment?.id) throw new Error('Appointment not persisted');
      event.stage = creation.appointment.status === 'pending_payment' ? 'Aguardando sinal' : 'Agendamento confirmado';
      event.service = 'agendamento';
      event.raw_payload.appointment_creation = creation;
      const dateDisplay = appointmentDateLabel(creation.appointment);
      responseText = creation.appointment.status === 'pending_payment'
        ? 'Perfeito, ' + tag.customerName + '! Seu pr\u00e9-agendamento para ' + service.name + ' em '
          + dateDisplay + ' foi registrado e fica pendente do pagamento do sinal.'
        : 'Seu agendamento foi registrado para ' + dateDisplay + '.';
    } catch (error) {
      responseText = 'Não consegui registrar esse horário. Me confirme o serviço, a data e o horário desejados para eu verificar?';
      event.ai_error = 'appointment_not_created';
      event.raw_payload.appointment_creation = { created: false, reason: error.message };
    }
  } else if (actions.humanRequested || actions.complaint
    || requestAction?.kind === 'update' || (requestAction?.kind === 'cancel' && !writableRequestAction)) {
    event.handoff = true;
    event.stage = 'Atendimento humano';
    event.service = 'atendimento_humano';
    event.raw_payload.explicit_handoff = true;
  } else if (needsTeamReview) {
    if (keepsAiOnTeamReview(context)) {
      event.handoff = false;
      event.stage = 'Aguardando confirmação';
      event.service = 'agendamento_pendente';
      event.raw_payload.team_review_requested = true;
    } else {
      event.handoff = true;
      event.stage = 'Atendimento humano';
      event.service = 'atendimento_humano';
    }
  }
  if (event.raw_payload.explicit_handoff && ['update', 'cancel'].includes(requestAction?.kind)) {
    responseText = sessionHandoffMessage(context);
    preserveLiteralReply = true;
    literalReplySuffix = '';
  }
  // Mantém o estágio alinhado ao estado persistido do agendamento em cada turno.
  if (!event.handoff && requestConfig?.valid) {
    if (appointments.openRequest) {
      event.stage = 'Aguardando confirmação';
      event.service = 'agendamento_pendente';
    } else if (appointments.futureConfirmed) {
      event.stage = 'Agendamento confirmado';
    }
  }
  const proseForCleanup = literalReplySuffix && responseText.includes(literalReplySuffix)
    ? responseText.replace(literalReplySuffix, '').trim()
    : responseText;
  let clean = preserveLiteralReply
    ? cleanReplyText(proseForCleanup)
    : enforceEmojiPolicy(cleanReplyText(proseForCleanup), history,
      { service: actions.complaint ? 'reclamacao' : 'geral', handoff: event.handoff });
  if (literalReplySuffix && !creation && !event.ai_error) {
    clean = [clean, literalReplySuffix].filter(Boolean).join('\n\n');
  }
  const salonAdapter = typeof helpers.salonAdapterDiagnostics === 'function' ? helpers.salonAdapterDiagnostics() : null;
  if (salonAdapter) Object.assign(event.raw_payload, salonAdapter);
  // Quais marcações a IA devolveu (sem o texto), para diagnosticar o turno depois.
  event.raw_payload.reply_actions = { human_requested: Boolean(actions.humanRequested), complaint: Boolean(actions.complaint),
    appointment_tag: requestAction ? requestAction.kind : (tag ? 'legacy_create' : null), text_empty: !clean };
  // Resposta só com marcações: nunca envia texto vazio (a Evolution recusa com 400 e a pessoa fica sem resposta).
  if (!clean) {
    if (!event.handoff) throw new Error('EMPTY_CUSTOMER_REPLY');
    clean = sessionHandoffMessage(context);
  }
  event.raw_payload.catalog_lookup = { count: catalog.matches.length, mode: catalog.mode };
  await saveEvent(event);
  const sent = await sendChannelMessage(context, clean, event);
  await complete('done');
  return { ok: true, ...sent, appointment_id: creation?.appointment?.id || null, grouped: turn.messages.length };
}

try {
  const turnResult = await runTurn();
  // A skipped prepare turn (contact excluded, superseded, commercial number...) is terminal.
  // It must keep the tenant identity so the router sends it straight to finalize instead of
  // calling the tenant extension again, where the identity guard would (rightly) reject it.
  if (noriaPhase === 'prepare' && turnResult && turnResult.skipped === true && turnResult.noria_terminal !== true) {
    return { json: {
      ...turnResult, noria_terminal: true, tenant_id: inputJson.tenant_id, tenant_slug: tenantSlug,
      instance: inputJson.instance || '', remoteJid: chatId,
      noria_extension: inputJson.noria_extension || undefined,
    } };
  }
  return { json: turnResult };
} catch (error) {
  const raisedToken = supabaseRaisedToken(error);
  const errorCode = (raisedToken && /^Request failed with status code \d+$/.test(String(error.message || ''))
    ? 'SUPABASE_RAISED:' + raisedToken : String(error.message || 'processing_failed')).slice(0, 300);
  const failure = {
    delivery_uncertain: sendAttempted && !deliveryConfirmed,
    provider_accepted: providerAccepted, delivery_confirmed: deliveryConfirmed,
    turn_committed: turnCommitted, retry_queued: false,
    requires_technical_intervention: true,
    turn_token: turn?.token || null, conversation_session_id: turn?.boundary_id || null,
    grouped_message_ids: (turn?.messages || []).map(item => item.id),
    ...(error?.noria_http ? { http_failure: error.noria_http } : {}),
    ...(deliveryAttemptId ? { delivery_attempt_id: deliveryAttemptId } : {}),
    ...(providerMessageId ? { provider_message_id: providerMessageId } : {}),
  };
  if (turn?.claimed && !turnFinished) {
    // A commit timeout can mean the database already entered sending. Read the
    // durable phase for diagnosis; never infer retry safety from sendAttempted.
    // Retry eligibility, persisted budget/backoff and delivery evidence are
    // decided under the queue lock by the paired lifecycle migration.
    try {
      const queue = await turnQueueState();
      failure.queue_phase = queue?.phase || 'missing';
      failure.queue_token_matches = queue?.token === turn.token;
    } catch (stateError) {
      failure.queue_phase = 'unknown';
      failure.queue_state_error = String(stateError.message || stateError).slice(0, 300);
    }
    const diagnostic = salesSafeFailureDiagnostics(error, 'turn_lifecycle');
    // Contract-version refusals happen before any commercial effect or send. They are retryable inside the persisted budget:
    // magia_fail_turn still routes a turn with a delivery attempt to uncertain and an exhausted budget to review.
    const retryable = (diagnostic.retryable === true
      && ['rate_limit', 'upstream_server', 'network_or_timeout'].includes(diagnostic.category))
      || (CONTRACT_CUTOVER_PATTERN.test(errorCode) && !sendAttempted)
      || (!sendAttempted && (errorCode === 'TURN_CONTROL_ORIGIN_REQUIRED' || turnFailureIsTransient(diagnostic)));
    failure.finish_requested = deliveryConfirmed ? 'done' : 'fail';
    failure.failure_retryable = retryable;
    const deliveryRejected = turnDeliveryRejectedByProvider(error, { sendAttempted, providerAccepted, deliveryConfirmed });
    failure.delivery_rejected = deliveryRejected;
    const failArgs = { p_tenant: inputJson.tenant_id, p_chat: chatId, p_token: turn.token, p_error: errorCode, p_retryable: retryable };
    const failTurn = async () => {
      if (!deliveryRejected) return supabasePost('/rest/v1/rpc/magia_fail_turn', failArgs);
      try {
        return await supabasePost('/rest/v1/rpc/magia_fail_turn', { ...failArgs, p_delivery_rejected: true });
      } catch (rpcError) {
        // Migração turn_fail_provider_rejected_v1 ainda não aplicada: a RPC antiga mantém o turno em reconciliação (uncertain).
        if (!/PGRST202/.test(supabaseErrorText(rpcError) + ' ' + String(rpcError?.noria_http?.code || ''))) throw rpcError;
        failure.delivery_rejected_rpc = 'unsupported';
        return supabasePost('/rest/v1/rpc/magia_fail_turn', failArgs);
      }
    };
    try {
      const result = deliveryConfirmed ? await complete('done') : await failTurn();
      if (result?.finished !== true || result.contract !== 'noria_turn_lifecycle_v1') {
        throw new Error('TURN_FAILURE_NOT_PERSISTED:' + String(result?.reason || 'rpc_contract_mismatch'));
      }
      failure.finish_persisted = true;
      failure.finish_outcome = result.outcome;
      failure.delivery_uncertain = result.outcome === 'uncertain'
        || (sendAttempted && !deliveryConfirmed && result.reason !== 'provider_rejected_delivery');
      failure.retry_queued = result.retry_queued === true;
      failure.requires_technical_intervention = !failure.retry_queued;
      failure.hold_reason = result.reason || (deliveryConfirmed ? 'confirmed_delivery_finalize_failed' : result.outcome);
    } catch (finishError) {
      failure.finish_persisted = false;
      failure.finish_error = String(finishError.message || finishError).slice(0, 300);
    }
    await supabasePost('/rest/v1/channel_events', {
      tenant_id: inputJson.tenant_id, tenant_slug: tenantSlug, channel_type: 'whatsapp', external_conversation_id: chatId,
      external_message_id: 'technical_' + String(turn.token || Date.now()), direction: 'outbound', sender_type: 'system',
      contact_name: turn.messages?.at(-1)?.name || firstName, message_text: '', service: 'technical_error', stage: 'Erro técnico',
      handoff: false, ai_provider: 'core_error', ai_model: null, ai_error: errorCode, ai_usage: {}, delivery_status: 'failed',
      raw_payload: failure,
    }).catch(auditError => {
      failure.audit_error = String(auditError.message || auditError).slice(0, 300);
    });
  }
  return {
    json: {
      ok: false, noria_terminal: true, tenant_id: inputJson.tenant_id, tenant_slug: tenantSlug,
      instance: inputJson.instance, remoteJid: chatId, noria_extension: inputJson.noria_extension,
      error: errorCode, ...failure,
    }
  };
}

